import os
import re


def load_frontmatter(root: str) -> dict:
    """Map each skill directory name to its parsed frontmatter dict.

    Values are strings, lists of strings, or nested dicts one level deep.
    A file with no frontmatter block is skipped.
    """
    out = {}
    for name in os.listdir(root):
        path = os.path.join(root, name, "SKILL.md")
        if not os.path.exists(path):
            continue
        text = open(path).read()
        block = text.split("---")[1]
        fields = {}
        for line in block.splitlines():
            m = re.match(r"(\w+): (.*)", line)
            if m:
                fields[m.group(1)] = m.group(2)
        out[name] = fields
    return out
